def main():
    path = 'assets/vintagee/lang/en.json'
    d = json.load(open(path, encoding='utf-8'), object_pairs_hook=collections.OrderedDict)
    missing = [k for k in NEW if k not in d]
    if missing and missing != ['doctor-copy']:
        print('keys not in en.json:', missing); sys.exit(1)
    ph = re.compile(r'\{(\d+)\}')
    bad = []
    for k, v in NEW.items():
        if k in d and set(ph.findall(d[k])) != set(ph.findall(v)): bad.append(k)
    if bad:
        print('placeholder mismatch:', bad); sys.exit(1)
    changed = sum(1 for k, v in NEW.items() if d.get(k) != v)
    d.update(NEW)
    with open(path, 'w', encoding='utf-8') as f:
        json.dump(d, f, ensure_ascii=False, indent=2); f.write('\n')
    print('rewritten', changed, 'of', len(NEW))

if __name__ == '__main__':
    main()
